insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('bc7824c8-ff2a-480a-99d4-f6fb94b160af', 'eed40822-df31-4f50-a71b-49d9c626adf0', $$tekstfragment — geschiedenis van koper en brons (regels 1-26)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-brons-context1.png$$,
   $$(regel 1) Zo''n 5000 jaar geleden waren mensen al in staat koper te winnen uit het
(regel 2) mineraal malachiet. Malachiet wordt weergegeven met de formule
(regel 3) Cu₂(OH)₂CO₃. Koper werd in die tijd in een zogenoemde vuurplaats
(regel 4) gemaakt. Daarbij werd een hoeveelheid malachiet gemengd met een
(regel 5) ruime hoeveelheid houtskool (koolstof). Dit mengsel werd daarna bedekt
(regel 6) met houtskool. Dit houtskool werd verbrand. Door de warmte die hierbij
(regel 7) vrijkwam, ontleedde het malachiet tot koper(II)oxide (CuO), water en
(regel 8) koolstofdioxide.
(regel 9) Het ontstane koper(II)oxide werd vervolgens door de reactie met de
(regel 10) overgebleven koolstof omgezet tot koper.
(regel 11) Brons is toevallig ontdekt. Omdat de vuurplaats verontreinigd was met
(regel 12) casseriet, een mineraal dat voornamelijk uit SnO₂ bestaat, had het
(regel 13) materiaal dat werd gevormd een andere kleur dan men gewend was.
(regel 14) Voorwerpen gemaakt van dit materiaal (brons) bleken sterker dan
(regel 15) koperen voorwerpen. Vanaf deze ontdekking maakte men brons door een
(regel 16) mengsel van malachiet, casseriet en houtskool op eenzelfde manier te
(regel 17) laten reageren als bij de productie van koper. SnO₂ wordt daarbij omgezet
(regel 18) tot tin dat met het gevormde koper samensmelt tot vloeibaar brons.
(regel 19) Tegenwoordig wordt brons gemaakt door het mengen van vloeibaar koper
(regel 20) en vloeibaar tin. Dit vloeibare mengsel wordt vervolgens in vormen
(regel 21) gegoten. Na afkoelen kan het vaste brons worden bewerkt tot voorwerpen
(regel 22) zoals kranen en beelden. Voor kranen van waterleidingen wordt veelal
(regel 23) brons gebruikt dat 10 massaprocent tin bevat. Deze bronssoort wordt in
(regel 24) de materiaalkunde aangeduid als CuSn10. Het is sterker en harder dan
(regel 25) koper en minder gevoelig voor aantasting door water in combinatie met
(regel 26) zuurstof en/of opgeloste zouten.$$, 'inline'),
  ('8958a38c-184e-4c9b-94da-c6de9c4cfc03', 'eed40822-df31-4f50-a71b-49d9c626adf0', $$malachiet als mengsel van twee zouten$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-brons-context2.png$$,
   $$Malachiet kan worden opgevat als een mengsel van twee zouten.$$, 'inline'),
  ('32f280e9-d3a0-4ffc-b7c1-bcc3222621f9', 'eed40822-df31-4f50-a71b-49d9c626adf0', $$vorming van koper uit koper(II)oxide is een redoxreactie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-brons-context3.png$$,
   $$De vorming van koper uit koper(II)oxide (regels 9 en 10) is een redoxreactie.$$, 'inline'),
  ('6daadea9-ec9c-4078-b7a6-2eb54bb72a2e', 'eed40822-df31-4f50-a71b-49d9c626adf0', $$notatie CuₓSny voor de atomaire samenstelling van een bronssoort$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-brons-context4.png$$,
   $$Bronssoorten worden, behalve met een aanduiding als CuSn10, ook wel aangeduid met een formule die de atomaire samenstelling van de bronssoort weergeeft, bijvoorbeeld CuₓSny.$$, 'inline'),
  ('8e0abd15-94ee-4244-afe2-cf5ac9900103', 'eed40822-df31-4f50-a71b-49d9c626adf0', $$brons geleidt elektrische stroom$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-brons-context5.png$$,
   $$Brons geleidt elektrische stroom. Om dit te verklaren kan een beschrijving worden gebruikt van het kristalrooster van brons.$$, 'inline'),
  ('2d89fd6f-3ed9-46d8-905f-cbaa4984bb82', 'aadd2a46-00b0-4b31-8b1d-9bac88c15396', $$intro — maniokmeel, zetmeel en de afbraak tot glucose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-maniok-context1.png$$,
   $$Maniokmeel (cassavemeel) wordt gewonnen uit de wortelknol van de maniokplant en veel gegeten in Zuid-Amerika en Afrika. Het is een voedingsbron die rijk is aan het koolhydraat zetmeel en weinig eiwit en vet bevat. In het menselijk lichaam verloopt de afbraak van zetmeel in grote lijnen via twee reactietypen. Glucose is hierbij een tussenproduct.$$, 'inline'),
  ('034c1bd7-b4fb-454e-a00f-39df6123ab4c', 'aadd2a46-00b0-4b31-8b1d-9bac88c15396', $$productiemethode maniokmeel — linamarine en nitrilgroep$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-maniok-context2.png$$,
   $$Bij de productie van maniokmeel gaat men via een speciale methode te werk om een giftige stof die voorkomt in de maniokknol onschadelijk te maken. De knollen worden eerst geschild en gedroogd. Daarna worden ze in stukken gesneden en minstens drie dagen in water gelegd. Vervolgens worden de stukken uit het water gehaald, gedroogd en fijngemalen tot meel.
De giftige verbinding in de maniokknol is linamarine (C₁₀H₁₇NO₆). In een molecuul linamarine komt een nitrilgroep (–CN) voor. Bij de hierboven beschreven methode komt een enzym vrij dat linamarine omzet tot glucose en acetoncyaanhydrine. Deze omzetting is in figuur 1 onvolledig weergegeven.$$, 'inline'),
  ('7e02b5a6-b39e-4964-a2f1-e161d58b733c', 'aadd2a46-00b0-4b31-8b1d-9bac88c15396', $$figuur 1 — omzetting van linamarine tot glucose en acetoncyaanhydrine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-maniok-context3.png$$,
   $$figuur 1: de onvolledige reactievergelijking (in structuurformules) van de omzetting van linamarine met water tot glucose en acetoncyaanhydrine. Linamarine is een ringstructuur (zoals glucose) met een O-C(CH₃)₂-CN-zijgroep op de plaats waar bij glucose een OH-groep zit; na reactie met H₂O ontstaat glucose (de ringstructuur met OH in plaats van de zijgroep) plus een niet-getekend tweede product, aangeduid met '…' (acetoncyaanhydrine).$$, 'inline'),
  ('4dc1c803-b266-45a2-b145-7761241af7ca', 'aadd2a46-00b0-4b31-8b1d-9bac88c15396', $$C-O-C-groep verbroken in figuur 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-maniok-context4.png$$,
   $$In de vergelijking van figuur 1 wordt uitsluitend een C-O-C-groep verbroken.$$, 'inline'),
  ('2c5b8dbe-122c-4b5d-8cb8-3c664abea7a6', 'aadd2a46-00b0-4b31-8b1d-9bac88c15396', $$vorming van waterstofcyanide (HCN)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-maniok-context5.png$$,
   $$Acetoncyaanhydrine ontleedt vervolgens. Hierbij ontstaat onder andere het giftige waterstofcyanide (blauwzuur). Dit verdampt bij de hierboven beschreven methode. Waterstofcyanide heeft de molecuulformule HCN.$$, 'inline'),
  ('ed6d2c68-9376-4dd9-9b65-8b57cfecf4d3', 'aadd2a46-00b0-4b31-8b1d-9bac88c15396', $$zwavelhoudend aminozuur — voorlichting en bladeren van de maniokplant$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-maniok-context6.png$$,
   $$Door voorlichting te geven over de juiste productiewijze van maniokmeel wordt geprobeerd de ziekte konzo terug te dringen. Ook wordt onderzocht of het eten van eiwitten die voldoende zwavel bevatten de ziekte kan voorkomen. Bij dat onderzoek heeft men eerst gekeken naar de bladeren van de maniokplant. Deze bevatten veel eiwitten en worden vaak als bijgerecht gegeten. Bij het onderzoek bestond vooral aandacht voor het gehalte aan één bepaald zwavelhoudend aminozuur dat mensen niet zelf kunnen maken, maar via hun voeding binnen moeten krijgen.$$, 'inline'),
  ('67ac4f6c-740c-4443-9709-2de046bab1bf', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$intro — hardheid van water in °D en Ca²⁺-concentratie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context1.png$$,
   $$Water met een hoog gehalte aan calciumionen noemen we hard water. De hardheid van water wordt vaak uitgedrukt in Duitse hardheidsgraden, °D. Water met een hardheid van 1,00 °D bevat 7,17 mg Ca²⁺ per liter. Leidingwater in Nijmegen bevat 2,2·10⁻³ mol Ca²⁺ per liter.$$, 'inline'),
  ('891e8755-317e-4c71-b6c3-b51d475c2396', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$kalkaanslag — reactievergelijking vorming van CaCO₃$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context2.png$$,
   $$Wanneer hard water wordt verhit, ontstaat een witte aanslag van kalk (CaCO₃). Dit ontstaan van kalkaanslag kan met de volgende reactievergelijking worden weergegeven:
Ca²⁺ + 2 HCO₃⁻ → CaCO₃ + H₂O + CO₂$$, 'inline'),
  ('90d2e77f-cf32-4643-9263-2d81a51becc6', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$tekstfragment — kalk verwijderen met natuurazijn (Wikipedia)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context3.png$$,
   $$Een waterkoker met een dompelaar als verwarmingselement zal na verloop van tijd veel kalk op het verwarmingselement krijgen. Dit kan simpel worden verwijderd door de waterkoker te vullen met natuurazijn. Na een paar minuten is de kalk in de azijn opgelost. Deze azijn kan vele malen worden hergebruikt als ontkalker, wanneer deze onverdund wordt gebruikt.
naar: Wikipedia$$, 'inline'),
  ('262fc9f0-6759-4cee-8402-8a9e006759b1', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$natuurazijn — zuur-basereactie met kalk$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context4.png$$,
   $$Natuurazijn is een oplossing van azijnzuur in water. Het verwijderen van kalk met behulp van natuurazijn komt neer op de volgende zuur-basereactie:
CaCO₃ + 2 CH₃COOH → Ca²⁺ + H₂O + CO₂ + 2 CH₃COO⁻$$, 'inline'),
  ('87c4fdc2-05a1-4107-90f7-05080b2ce5b1', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$advies: azijn in de waterkoker aan de kook brengen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context5.png$$,
   $$Op de website www.VoorOma.nl staat het advies de azijn in de waterkoker even aan de kook te brengen.$$, 'inline'),
  ('ba98d8b2-6829-420f-bc40-2b6e00858185', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$reactiewarmte kalk met azijnzuur — onvolledig energiediagram$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context6.png$$,
   $$Emine berekent op school de reactiewarmte voor de reactie van kalk met azijnzuur. Ze komt uit op ∆E = –1,2·10⁴ J per mol CaCO₃. Op de uitwerkbijlage is een nog onvolledig energiediagram gegeven van deze reactie.$$, 'inline'),
  ('21b4433a-52f7-4fd9-bd9a-252e69e8baac', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$uitwerkbijlage vraag 15 — onvolledig energiediagram$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context7.png$$,
   $$uitwerkbijlage bij vraag 15: een onvolledig energiediagram (energie op de y-as) van de reactie van kalk met azijnzuur. Alleen het energieniveau van de beginstoffen is al ingetekend; de leerling moet het energieniveau van de geactiveerde toestand en van de reactieproducten tekenen en ∆E aangeven, met bijschriften.$$, 'uitwerkbijlage'),
  ('e154228b-2d58-4000-88c8-9659bb71d1ac', '5c96dc83-5cbc-49f0-8aa4-1e0b305c4c05', $$verchroomd verwarmingselement — bescherming door een chroomoxidelaagje$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-hard-water-context8.png$$,
   $$Het verwarmingselement van waterkokers is vaak gemaakt van koper waarop een laagje chroom is aangebracht. Hoewel chroom een onedeler metaal is dan koper, is zo''n verchroomd verwarmingselement toch bestand tegen corrosie. Door reactie met zuurstof ontstaat namelijk op het chroom een laagje chroomoxide dat verdere aantasting van het chroom verhindert.$$, 'inline'),
  ('836fe5db-07d7-46a7-95c9-d0e44478db89', 'db2e174b-6cc8-4dc6-a376-d6bcf47f5f0b', $$halfreacties zilveroxidebatterij (Ag₂O/Zn)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-zalmbatterijtje-context1.png$$,
   $$Ag₂O + H₂O + 2 e⁻ → 2 Ag + 2 OH⁻
Zn + 2 OH⁻ → ZnO + H₂O + 2 e⁻$$, 'inline'),
  ('bb9954b9-0330-4555-84f6-f230af0f33dc', 'db2e174b-6cc8-4dc6-a376-d6bcf47f5f0b', $$constructie van het zalmbatterijtje (laagjes)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-zalmbatterijtje-context3.png$$,
   $$Het batterijtje wordt als volgt gemaakt:
− Een aluminiumgaasje wordt ingesmeerd met een pasta van carbofluor.
− Dit gaasje wordt tussen twee dunne laagjes polypropeen (PP) gelegd.
− Daarop komt een dun velletje lithium.
− Aan de elektroden (het aluminiumgaasje en het lithiumvelletje) zijn koperdraadjes bevestigd.
− De vier laagjes worden opgerold en in een kokertje gestopt.
− Het kokertje wordt gevuld met elektrolyt en daarna dichtgemaakt.
− Alleen de twee koperdraadjes steken uit het kokertje.$$, 'inline'),
  ('e4aec91f-a446-47d9-828c-cf841f1b9611', 'db2e174b-6cc8-4dc6-a376-d6bcf47f5f0b', $$halfreacties zalmbatterijtje (CFₓ/Li)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-zalmbatterijtje-context5.png$$,
   $$Wanneer het batterijtje stroom levert, treden de volgende halfreacties op:
CFₓ + x e⁻ → C + x F⁻
Li → Li⁺ + e⁻$$, 'inline'),
  ('60587e1a-2edc-4de3-abc2-e862b7098b25', 'db2e174b-6cc8-4dc6-a376-d6bcf47f5f0b', $$figuur 2 — microscoopopname van polypropeen met gaatjes$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-zalmbatterijtje-context6.png$$,
   $$Figuur 2 toont een microscoopopname van een deel van het laagje polypropeen. figuur 2: elektronenmicroscoopopname van een stukje polypropeenfolie, met een onregelmatig netwerk van langwerpige poriën (gaatjes) van ongeveer 1·10⁻⁶ m grootte.$$, 'inline'),
  ('8d5b2ba4-0842-43ec-a267-2fc05f770dc7', 'db2e174b-6cc8-4dc6-a376-d6bcf47f5f0b', $$polypropeen heeft gaatjes (uit figuur 2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-zalmbatterijtje-context7.png$$,
   $$In figuur 2 is te zien dat het polypropeen niet dicht is, maar gaatjes heeft.$$, 'inline'),
  ('e29c6401-1a91-4021-840b-3a9184b2b9ac', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$intro — ECN Petten: methaanproces uit hout (R1/R2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context1.png$$,
   $$Bij ECN in Petten is een proces ontwikkeld waarbij methaan uit (afval)hout wordt geproduceerd. Sinds 2015 draait er een proeffabriek volgens dat proces. Een essentieel onderdeel van de fabriek is een zogenoemde vergassingsreactor (R1) waarin hout bij ongeveer 850 °C wordt omgezet tot een mengsel van verschillende gassen. De warmte die hiervoor nodig is, wordt geleverd door een verbrandingsreactor (R2) die voornamelijk wordt gevoed met hout. In onderstaand blokschema zijn deze onderdelen van de fabriek vereenvoudigd weergegeven.$$, 'inline'),
  ('1a8cea09-1eda-4860-b4da-6eafa0ce988e', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$blokschema — hout naar methaan (R1, R2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context2.png$$,
   $$blokschema: hout wordt toegevoerd aan zowel R1 als R2; in R1 (met stoom als extra toevoer) ontstaat productgas; R2 krijgt lucht toegevoerd en levert verbrandingsgassen + stikstof.$$, 'inline'),
  ('abbb2be6-7f9b-4694-819f-52354a7380e3', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$reactie 1 — vorming van CO en H₂ uit hout$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context3.png$$,
   $$Het productgas dat de vergassingsreactor (R1) verlaat, bestaat voor een belangrijk gedeelte uit koolstofmono-oxide en waterstof. De vorming van deze gassen verloopt volgens reactie 1. In deze reactievergelijking is hout vereenvoudigd weergegeven met de formule C₆H₁₀O₅.
C₆H₁₀O₅ (s) + H₂O (g) → 6 CO (g) + 6 H₂ (g)  reactie 1$$, 'inline'),
  ('bb27b83c-4589-4b8d-94da-9212ac2d211c', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$scheiding S1/S2 — teer en benzeen afscheiden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context4.png$$,
   $$Behalve CO en H₂ bevat het productgas ook CO₂, C₂H₄, C₆H₆ (benzeen) en hogere koolwaterstoffen (koolwaterstoffen met een groter aantal C-atomen per molecuul). De hogere koolwaterstoffen worden in een eerste scheidingsruimte (S1) door afkoeling uit het productgas afgescheiden als teer. De teer wordt naar de verbrandingsreactor (R2) geleid, waar het ook wordt verbrand. In een tweede scheidingsruimte (S2) wordt het overgebleven productgas verder afgekoeld zodat benzeen als vloeistof wordt afgescheiden. Dit kan worden gebruikt als grondstof in de kunststofindustrie.$$, 'inline'),
  ('cec539f9-2bc9-4725-9cd5-6969334a46ae', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$benzeengehalte productgas (0,35 volumeprocent)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context5.png$$,
   $$Het benzeengehalte van het productgas is afhankelijk van het soort hout dat in de vergassingsreactor (R1) wordt ontleed. Bij een bepaald soort hout bevat het productgas uit de vergassingsreactor 0,35 volumeprocent benzeen (C₆H₆).$$, 'inline'),
  ('5fc6133e-d18a-4154-8c88-f27d800e98bb', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$reactie 2 — vorming van methaan uit CO$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context6.png$$,
   $$Het CO uit het productgas wordt in een reactor (R3) omgezet tot methaan. Deze omzetting wordt met de volgende reactievergelijking weergegeven:
CO + 3 H₂ → CH₄ + H₂O  reactie 2$$, 'inline'),
  ('5ce4956e-8eab-4393-9a44-f5f7376392d3', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$overige omzettingen in R3 — ontbrekende stofstromen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context7.png$$,
   $$Ook de andere stoffen uit het productgas worden in R3 omgezet tot methaan. Voor al deze omzettingen in R3 is extra waterstofgas nodig. Op de uitwerkbijlage bij dit examen is een nog onvolledig blokschema van het beschreven proces weergegeven. Er ontbreekt een aantal stofstromen.$$, 'inline'),
  ('8304099b-428f-48cd-94f5-4fb2f6bb2a80', '8f37a885-d573-4446-b27b-7b76ff61ed70', $$uitwerkbijlage vraag 28 — onvolledig blokschema (S1, S2, R3)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-methaan-uit-hout-context8.png$$,
   $$uitwerkbijlage bij vraag 28: het blokschema uitgebreid met scheidingsruimtes S1, S2 en reactor R3 na R1/R2: hout → R1/R2 → productgas → S1 → S2 → R3, met de bestaande stofstromen (hout, stoom, lucht, verbrandingsgassen + stikstof, productgas) al getekend, maar zonder de stofstromen tussen S1–S2–R3 (teer naar R2, benzeen uit S2, extra waterstofgas naar R3, methaan uit R3).$$, 'uitwerkbijlage'),
  ('e3853b6e-b686-463e-a0d6-f2e5baf53140', '08a977cf-bd04-4975-9176-a89eda62b30f', $$TCE wordt gebruikt om textiel te reinigen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-biopad-context1.png$$,
   $$De vloeistof TCE wordt gebruikt om bepaalde soorten textiel te reinigen.$$, 'inline'),
  ('e93ebcec-2052-49e2-a022-888373c58e47', '08a977cf-bd04-4975-9176-a89eda62b30f', $$vorming en zuivering met BioPAD (Pd-korreltjes, waterstofatomen)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-biopad-context2.png$$,
   $$Om BioPAD te vormen (figuur 1A) wordt eerst een oplossing van methaanzuur (HCOOH) toegevoegd aan een suspensie van bacteriën. Daarna wordt een oplossing van palladiumchloride (PdCl₂) toegevoegd. Onder invloed van enzymen in de bacteriën treedt een reactie op. Hierbij wordt HCOOH omgezet tot CO₂ en wordt het metaal palladium gevormd uit Pd²⁺-ionen. Het gevormde palladium hecht zich in de vorm van zeer kleine korreltjes (met een diameter van ongeveer 30 nanometer) aan de celwand van de bacteriën. De bacteriën sterven vervolgens af. De celwand blijft echter heel. Tijdens het zuiveringsproces (figuur 1B) wordt H₂-gas toegevoegd, waarbij waterstofatomen zich hechten aan de palladiumkorreltjes.$$, 'inline'),
  ('a3d608ca-6801-465e-b8fe-52bc9b1f93df', '08a977cf-bd04-4975-9176-a89eda62b30f', $$figuur 1B — zuiveringsproces: TCE + BioPAD → ethaan + waterstofchloride$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-biopad-context3.png$$,
   $$figuur 1B (zuiveringsproces): BioPAD (een Pd-deeltje met waterstofatomen eraan gehecht) reageert met TCE tot ethaan en een oplossing van waterstofchloride, waarbij het Pd-deeltje zijn waterstofatomen verliest.$$, 'inline'),
  ('424835cb-9c58-4f7c-91d6-2915724f4724', '08a977cf-bd04-4975-9176-a89eda62b30f', $$onvolledige vergelijking zuiveringsproces (TCE → ethaan)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-biopad-context4.png$$,
   $$De vergelijking van de totale reactie die optreedt tijdens het zuiveringsproces (figuur 1B) is hieronder schematisch weergegeven.
BioPAD
TCE + … → ethaan + … + …$$, 'inline'),
  ('ecc4065d-385c-48e1-bc77-25edfb7e3f51', '08a977cf-bd04-4975-9176-a89eda62b30f', $$voordeel van BioPAD als katalysator (geen samenklontering)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-biopad-context5.png$$,
   $$Voor de omzetting van TCE tot onder andere ethaan zou ook palladiumpoeder als katalysator gebruikt kunnen worden. Een belangrijk voordeel van BioPAD als katalysator is dat de Pd-deeltjes niet samenklonteren tot grotere deeltjes.$$, 'inline'),
  ('bafd4de9-cee0-49b7-834c-039f2841f073', '08a977cf-bd04-4975-9176-a89eda62b30f', $$membraan houdt BioPAD tegen in de reactor$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-iii-biopad-context6.png$$,
   $$De zuivering van water dat verontreinigd is met TCE wordt uitgevoerd in een reactor waarin een membraan is aangebracht. De opgeloste stoffen kunnen het membraan passeren, maar BioPAD niet.$$, 'inline');

